import {create} from 'zustand'

export const useUser = create((set, get) => ({
    data: {name: "",image: ""},
    addData: (name, image) => {
        set({data: {name, image}});
    }
}));

export const useData = create((set, get) => ({
    data: [{
        nameProject: "Укроп",
        dayCreateProject: "26.06.2024",
        deadlineProject: "30.06.2024",
        statusProject: "green",
        CountTask: 1,
        Tasks: [{
            nameTask: "Зелень",
            dayCreateTask: "26.06.2024",
            deadlineTask: "30.06.2024",
            dayTargetTask: "27.06.2024",
            statusTask: "green",
            Subtasks: [{
                nameSubtask: "Нарезать",
                statusSubtask: true
            }]
        }]
    },{
        nameProject: "Редис",
        dayCreateProject: "",
        deadlineProject: "",
        statusProject: "",
        CountTask: 0,
        Tasks: [{
            nameTask: "Корнеплод",
            dayCreateTask: "",
            deadlineTask: "",
            dayTargetTask: "",
            statusTask: "",
            Subtasks: [{
                nameSubtask: "",
                statusSubtask: ""
            }]
        }]
    }],
    addData: (prop) => {
        set({data: {prop}});
    }
}));
